(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/glyphs-0016.js"] = [{"id":"glyph-seal-54a6","script":"seal","character":"咦","reading":"yí","description":"yí：叹词，表示惊讶～！这是怎么回事？","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咦"},{"id":"glyph-seal-54a8","script":"seal","character":"咨","reading":"zī","description":"zī：(1)商议，询问～问。～访。～询。\n(2)用于同级机关的一种公文～文。\n(3)叹气的声音～嗟（a.叹息；b.赞叹）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咨"},{"id":"glyph-seal-54ab","script":"seal","character":"咫","reading":"zhǐ","description":"zhǐ：中国古代长度单位（周代指八寸，合现市尺六寸二分二厘）～尺。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咫"},{"id":"glyph-seal-54ac","script":"seal","character":"咬","reading":"yǎo","description":"yǎo：(1)上下牙对住，压碎或夹住东西～啮。～噬。～紧牙关。\n(2)钳子等夹住或螺丝齿轮等卡住～合。～住扣。\n(3)喻话说定了不再改变，亦指受责难或审讯时拉扯不相关的人一口～定。乱～好人。\n(4)狗叫鸡叫狗～。\n(5)正确地读字音，亦指过分地计较字句的意义～字儿。～文嚼字（过分地斟酌字句，多用来讽刺死抠字眼儿而不领会精神实质）。\n(6)追赶进逼双方比分～得很紧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咬"},{"id":"glyph-seal-54b3","script":"seal","character":"咳","reading":"ké；hāi","description":"ké：〔～嗽〕呼吸器官受刺激而引起一种反射作用。把吸入的气急急呼出，同时发声，能清除呼吸道中的异物或痰，亦是某些病的症状。\nhāi：(1)叹息～声叹气。\n(2)叹词，表示惋惜或后悔又表示招呼人，提醒人注意～！我昨天没去医院。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咳"},{"id":"glyph-seal-54b8","script":"seal","character":"咸","reading":"xián","description":"毕;终\n感应\n普遍都,全部\n京城\n⒈都、皆～知。老少～宜。\n⒉盐的味道，跟\"淡\"相对～肉。菜～了。\n咸jiān 1.束棺木的绳索。\n咸jiǎn 1.通\"减\"。剪除;灭绝。参见\"咸黜\"。 2.姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咸"},{"id":"glyph-seal-54bd","script":"seal","character":"咽","reading":"yān；yàn；yè","description":"yān：口腔后部由肌肉和黏膜构成的管子，分三部分，上段与鼻腔相对称鼻咽”；中段与口腔相对称口咽”；下段在喉的后部称喉咽”。咽是呼吸道和消化道的共同通路（亦称咽头”）～喉。\n吐；\nyàn：使嘴里的食物或别的东西通过咽头到食道里去～唾沫。狼吞虎～。细嚼慢～。\n吐；\nyè：阻塞，声音因阻塞而低沉哽～。呜～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-咽"},{"id":"glyph-seal-54c0","script":"seal","character":"哀","reading":"āi","description":"āi：(1)悲痛悲～。～求。～叹。～鸣。～思。～鸿遍野（哀鸿”，哀鸣的大雁；喻到处都是呻吟呼号，流离失所的灾民）。～艳（诗文凄测动人而华丽）。\n(2)悼念～悼。默～。\n(3)旧时称死去母亲～子（a.母丧而父存；b.古称居父母丧的人）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哀"},{"id":"glyph-seal-54c1","script":"seal","character":"品","reading":"pǐn","description":"pǐn：(1)物件物～。产～。赠～。战利～。\n(2)等级，种类～名。～类。～色。～位。\n(3)性质～质。～行（xíng）。～节（指人的品行节操）。人～。\n(4)体察出好坏、优劣等～评。～第（品评优劣而定其等级）。～味（品尝）。\n(5)指吹弄乐器～箫。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-品"},{"id":"glyph-seal-54c4","script":"seal","character":"哄","reading":"hǒng；hōng；hòng","description":"hōng：好多人同时发声～传（chuán）。～动。\nhǒng：(1)说假话骗人～人。～弄。～骗。\n(2)用语言或行动逗人喜欢～逗。～劝。～小孩儿。\nhòng：吵闹，搅扰起～（故意吵闹扰乱，亦指开玩笑）。～场（指观众喝倒彩）。～抢。一～而起。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哄"},{"id":"glyph-seal-54c6","script":"seal","character":"哆","reading":"duō","description":"duō：〔～嗦〕发抖，战栗，如冷得打～～”（嗦”读轻声）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哆"},{"id":"glyph-seal-54c7","script":"seal","character":"哇","reading":"wa；wā","description":"wā：(1)象声词，形容哭声、呕吐声～地吐了一地。\n(2)指靡靡之音淫～。\nw：助词，大致相当于啊”（前面紧挨着的音一定是ｕ、ａｏ、ｏｕ等结尾的）多好～！快走～！","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哇"},{"id":"glyph-seal-54c9","script":"seal","character":"哉","reading":"zāi","description":"zāi：(1)文言语气助词（a.表疑问或反诘，相当于吗”，呢”，如何～？”有何难～？”b.表感叹，相当于啊”，如快～！”）。\n(2)古同才”，开始。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哉"},{"id":"glyph-seal-54cd","script":"seal","character":"响","reading":"xiǎng","description":"声音\n⒈声音～声。音～。\n⒉发出声音铃～了。炮～了。\n⒊回声空谷传～。\n⒋声音大，洪亮～彻云霄。～亮的歌声。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-响"},{"id":"glyph-seal-54d1","script":"seal","character":"哑","reading":"yǎ","description":"乌鸦之类的叫声\n婴儿学说话的声音\n相当于现代汉语的呀”\n哑 语气\n相当于呀”\n啞、瘂哑\n由于生理缺陷或疾病而失去言语功能\n⒈不能说话～巴。～口无言。\n⒉嗓子发音困难或不清楚沙～声～了。\n⒊不说话的～语。～剧。\n①小孩学说话的声音。\n②划桨的声音。［哑哑］\n①小儿学说话的声音。\n②乌鸦的叫声。\n哑è 1.笑声。参见\"哑哑\"﹑\"哑然\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哑"},{"id":"glyph-seal-54d3","script":"seal","character":"哓","reading":"xiāo","description":"恐惧\n吵嚷\n争辩\n话多\n①争辩的声音～ ～不休。\n②因恐惧而发出的叫声。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哓"},{"id":"glyph-seal-54d5","script":"seal","character":"哕","reading":"yue；hui","description":"打呃\n引申为欲言又止的样子\n呕吐。亦指呕吐物\n唾骂;唾弃\n唾,用力\n⒈呕吐～出来了。\n哕huì 1.鸟鸣。 2.象声词。参见\"哕哕\"。 3.见\"哕哕\"。 4.见\"哕息\"。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哕"},{"id":"glyph-seal-54d7","script":"seal","character":"哗","reading":"huá","description":"人声嘈杂,喧闹\n浮夸\n形容很响的笑声的\n哗变\n⒈人声嘈杂，乱吵笑语喧～。会场大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哗"},{"id":"glyph-seal-54d9","script":"seal","character":"哙","reading":"kuài","description":"吞咽\n喘息。张口舒气\n通快”。畅快;快意\n宽明\n平庸\n⒈咽下去。\n⒉〈古〉通\"快\"。畅快。\n哙kuò 1.见\"肿哙\"。\n哙huī 1.骡马打响鼻的声音。\n哙wèi 1.方言。句末语气助词。 2.叹词。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哙"},{"id":"glyph-seal-54e5","script":"seal","character":"哥","reading":"gē","description":"gē：(1)兄，同父母（或只同父，只同母）或同族同辈而年龄比自己大的男子～～。\n(2)称呼年龄跟自己差不多的男子李二～。\n(3)古同歌”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哥"},{"id":"glyph-seal-54e6","script":"seal","character":"哦","reading":"ò；ó；é","description":"ó：叹词，表示疑问、惊奇等～，是怎么回事？\nò：叹词，表示领会、醒悟～，我明白了。\né：〔吟～〕有节奏地诵读诗文。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哦"},{"id":"glyph-seal-54e8","script":"seal","character":"哨","reading":"shào","description":"shào：(1)巡逻，警戒防守的岗位～兵。～卡（qiǎ）。～所。岗～。放～。\n(2)古代军队的编制单位，历代标准不一。\n(3)一种小笛～子。\n(4)用口吹出的高尖音口～儿。\n(5)鸟叫。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哨"},{"id":"glyph-seal-54ed","script":"seal","character":"哭","reading":"kū","description":"kū：因痛苦或悲哀而流泪发声～喊。～泣。～诉。～腔。啼～。长歌当～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哭"},{"id":"glyph-seal-54ee","script":"seal","character":"哮","reading":"xiāo；xiào","description":"xiào：(1)吼叫咆～。\n(2)急促喘气的声音～喘。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哮"},{"id":"glyph-seal-54f2","script":"seal","character":"哲","reading":"zhé","description":"zhé：(1)有智慧～人。～嗣（称别人子孙的敬辞）。～理（关于宇宙和人生的原理）。～学（关于自然知识和社会知识的概括）。\n(2)聪明智慧的人先～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哲"},{"id":"glyph-seal-54fa","script":"seal","character":"哺","reading":"bǔ","description":"bǔ：(1)喂不会取食的幼儿～乳。～养。～育。\n(2)口里含着的食物一饭三吐～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哺"},{"id":"glyph-seal-54fd","script":"seal","character":"哽","reading":"gěng","description":"gěng：(1)声气阻塞～咽（yè）。～结。～塞（sè）。\n(2)食物阻塞在喉不能下咽～阻。～噎。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-哽"},{"id":"glyph-seal-5501","script":"seal","character":"唁","reading":"yàn","description":"yàn：吊丧，对遭遇丧事表示慰问～电（吊丧的电报）。吊～。慰～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唁"},{"id":"glyph-seal-5507","script":"seal","character":"唇","reading":"chún","description":"chún：嘴的边缘红色部分嘴～。～齿（喻互相接近而且有共同利害的两方面）。～膏。～裂。～舌（嘴唇”和舌头”，喻言辞）。～吻（嘴唇，喻口才、言辞）。～亡齿寒（关系密切，利害相关）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唇"},{"id":"glyph-seal-5509","script":"seal","character":"唉","reading":"āi；ài","description":"āi：(1)叹词，应人声。\n(2)叹息的声音～声叹气。\nài：叹词，表示伤感或惋惜～，病了几天，把事都耽误了。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唉"},{"id":"glyph-seal-550f","script":"seal","character":"唏","reading":"xī","description":"xī：(1)叹词，表示惊叹～，这字写得真漂亮！\n(2)叹息。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唏"},{"id":"glyph-seal-5510","script":"seal","character":"唐","reading":"táng","description":"táng：(1)夸大，虚夸荒～。～大无验。\n(2)空，徒然功不～捐（功夫不白费）。\n(3)传说中的中国朝代名，尧所建。\n(4)朝代名～代。～诗。～僧。～人。～三彩◇～。\n(5)古代朝堂前或宗庙门内的大路。\n(6)古同螗”，指蝉。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唐"},{"id":"glyph-seal-5520","script":"seal","character":"唠","reading":"láo；lào","description":"láo：说话烦琐，如唠叨。lào：方言中指闲谈，如唠嗑。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5524","script":"seal","character":"唤","reading":"huàn","description":"huàn：呼叫，喊～起。～醒。叫～。召～◆～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唤"},{"id":"glyph-seal-552c","script":"seal","character":"唬","reading":"hǔ；xià","description":"hǔ：(1)威吓（hè）虚张声势是～不住人的。\n(2)蒙混，蒙哄用流言～人。\nxià：同吓1”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唬"},{"id":"glyph-seal-552e","script":"seal","character":"售","reading":"shòu","description":"shòu：(1)卖～货。～票。出～。销～。零～。\n(2)施展以～其奸。其计不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-售"},{"id":"glyph-seal-552f","script":"seal","character":"唯","reading":"wéi","description":"wéi：(1)义同惟”①～物论。～心论。～物史观。～心史观。～理论。～名论。\n(2)答应的声音～～（a.谦卑的应答声；b.鱼相随而行的样子，如其鱼～～”）。～～诺诺。～～否否。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唯"},{"id":"glyph-seal-5531","script":"seal","character":"唱","reading":"chàng","description":"chàng：(1)依照乐（yuè）律发声～歌。～腔。～段。～功。～和（hè）。歌～。\n(2)高呼，大声叫～名。～收。\n(3)歌曲唱个～儿。\n(4)古同倡”，倡导。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唱"},{"id":"glyph-seal-5533","script":"seal","character":"唳","reading":"lì","description":"lì：鹤、雁等鸟高亢的鸣叫华亭鹤～，岂可复闻乎？”风声鹤～（形容惊慌疑惧）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唳"},{"id":"glyph-seal-553e","script":"seal","character":"唾","reading":"tuò","description":"tuò：(1)口腔里的消化液～液。～涎。～沫。\n(2)啐，从嘴里吐出来～弃（吐唾沫表示轻视、鄙弃）。～骂。～手可得。～面自干。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-唾"},{"id":"glyph-seal-5541","script":"seal","character":"啁","reading":"zhōu；zhāo；tiào","description":"zhōu：〔～啾〕形容鸟叫声。\n〔～噍〕形容鸟叫声。\nzhāo：〔～哳〕形容声音杂乱细碎。\ntiào：调笑孙权性既滑稽，嘲～无方”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啁"},{"id":"glyph-seal-5544","script":"seal","character":"啄","reading":"zhuó","description":"zhuó：鸟类用嘴叩击并夹住东西～食。～木鸟。鸡～米。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啄"},{"id":"glyph-seal-5546","script":"seal","character":"商","reading":"shāng","description":"shāng：(1)两个以上的人在一起计划、讨论～量。～讨。～议。～定。～榷。～酌（商量斟酌）。相～。磋～。洽～。协～。\n(2)买卖，生意～业。～店。～界。～品。～标。\n(3)古指行商（坐商为贾”，后泛指做买卖的人，亦用以指从事私营工商业的人）～人。～贩。～贾（gǔ）（商人）。～旅。\n(4)数学上指除法运算中的得数～数。\n(5)中国朝代名～代。\n(6)中国古代五音之一，相当于简谱2”。\n(7)星名，二十八宿之一，即心宿”。\n(8)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-商"},{"id":"glyph-seal-5550","script":"seal","character":"啐","reading":"cuì；qi","description":"cuì：(1)用力从嘴里吐出来～一口痰。\n(2)唾人以表示鄙斥。\n(3)尝，小饮不～酒。”\nqi：表示轻蔑的声音～，这有什么了不起！","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啐"},{"id":"glyph-seal-5555","script":"seal","character":"啕","reading":"táo","description":"táo：〔嚎～〕见嚎”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啕"},{"id":"glyph-seal-5556","script":"seal","character":"啖","reading":"dàn","description":"dàn：(1)吃或给人吃～饭。～以肉食。\n(2)拿利益引诱人～以私利。\n(3)古同淡”，清淡。\n(4)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啖"},{"id":"glyph-seal-555c","script":"seal","character":"啜","reading":"chuò；chuài","description":"chuò：(1)饮，吃～茶。～粥。\n(2)哭泣时抽噎的样子～泣。\nchuài：姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啜"},{"id":"glyph-seal-5567","script":"seal","character":"啧","reading":"zé","description":"大呼,大声喊叫\n争辩\n咂嘴\n同赜”。事物的幽深、细微处\n鸟声。多叠用\n啧啧野\n①鸟鸣声。\n②赞叹声～ ～称善。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啧"},{"id":"glyph-seal-556c","script":"seal","character":"啬","reading":"sè","description":"啬黍。\n⒈小气，该用的财物不用～刻。吝～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啬"},{"id":"glyph-seal-556e","script":"seal","character":"啮","reading":"niè","description":"侵蚀\n⒈咬鼠～。\n⒉缺口剑之折，必有～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啮"},{"id":"glyph-seal-5578","script":"seal","character":"啸","reading":"xiào","description":"呼召,号召\n⒈打口哨，撮口发音仰天长～。\n⒉动物长声吼叫虎～猿啼。\n⒊自然界产生的或子弹、飞机等飞过时所发出的声音海～。子弹～ ～擦耳掠过。飞机尖～着飞过屋顶。\n啸chì 1.大声呼喝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啸"},{"id":"glyph-seal-557b","script":"seal","character":"啻","reading":"chì","description":"chì：但，只何～。奚～。\n〔不～〕a.不止，不只，如～～如此”；b.不异于，如～～兄弟”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啻"},{"id":"glyph-seal-557c","script":"seal","character":"啼","reading":"tí","description":"tí：(1)哭，出声地哭～哭。～泣。悲～。～笑皆非。\n(2)鸟兽叫～鸣。～叫。虎啸猿～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啼"},{"id":"glyph-seal-557e","script":"seal","character":"啾","reading":"jiū","description":"jiū：〔～～〕象声词，形容动物细小的叫声，如～～鸟鸣”。\n〔～唧〕小声，如秋虫～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-啾"},{"id":"glyph-seal-5581","script":"seal","character":"喁","reading":"yóng","description":"yóng：鱼口向上，露出水面水浊则鱼～”。\n〔～～〕a.低声，如～～细语”；b.随声附和，如～～相和”；c.众人景仰归向的样子，如延颈举踵，～～然，皆争归义”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喁"},{"id":"glyph-seal-5582","script":"seal","character":"喂","reading":"wèi","description":"wèi：(1)叹词，打招呼时用～，您是哪位？\n(2)把食物送进人嘴里～奶。\n(3)给动物吃东西，饲养～养牲口。～马。～鱼。～狗。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喂"},{"id":"glyph-seal-5584","script":"seal","character":"善","reading":"shàn","description":"shàn：(1)心地仁爱，品质淳厚～良。～心。～举。～事。～人。～男信女。慈～。\n(2)好的行为、品质行～。惩恶扬～。\n(3)高明的，良好的～策。～本。\n(4)友好，和好友～。亲～⊥～。\n(5)熟悉面～。\n(6)办好，弄好～后。\n(7)擅长，长（cháng）于～辞令。多谋～断。\n(8)赞许群臣百姓之所～，则君～之”。\n(9)好好地～待。～罢甘休。\n(10)容易，易于～变。～忘。多愁～感。\n(11)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-善"},{"id":"glyph-seal-5588","script":"seal","character":"喈","reading":"jiē","description":"jiē：疾速的样子北风其～”。\n〔～～〕a.声音和谐，如鼓钟～～”；b.鸟声，如鸡鸣～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喈"},{"id":"glyph-seal-5589","script":"seal","character":"喉","reading":"hóu","description":"hóu：颈的前部和气管相通的部分，是呼吸器官的一部分，内有声带，又是发音器官（通称喉头”）～咙。～舌（a.泛指说话的器官；b.喻代言人，如报纸是人民的～～”；c.喻险要的地方，如居庸关乃扼守京城之～～”．；d.古喻国家的重臣，特指御史之类的谏官）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喉"},{"id":"glyph-seal-5591","script":"seal","character":"喑","reading":"yīn","description":"yīn：(1)哑，不能说话～哑难言。\n(2)缄默，不说话。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喑"},{"id":"glyph-seal-5594","script":"seal","character":"喔","reading":"wō；ō","description":"ō：叹词，表示理解、省悟～，真有这回事！\n〔～唷〕叹词，表示惊讶、痛苦，如～～，摔得好痛！”\nwō：象声词，形容雄鸡叫声雄鸡～～啼。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喔"},{"id":"glyph-seal-5598","script":"seal","character":"喘","reading":"chuǎn","description":"chuǎn：急促地呼吸～气。～息。～咳。苟延残～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喘"},{"id":"glyph-seal-5599","script":"seal","character":"喙","reading":"huì","description":"huì：(1)嘴，特指鸟兽的嘴长～。短～。\n(2)借指人的嘴百～莫辩。不容置～（不准插嘴）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喙"},{"id":"glyph-seal-559c","script":"seal","character":"喜","reading":"xǐ","description":"xǐ：(1)高兴，快乐欢～。～悦。～讯。～剧。～气。～色。～幸。～乐（lè）。～洋洋。欢天～地。欣～若狂。\n(2)可庆贺的，特指关于结婚的～事。～酒。～糖。～蛋。～联。～幛。～雨。～报。～庆∝～。报～。\n(3)妇女怀孕害～。她有～了。\n(4)爱好～爱。～好（hào）。～欢∶（hào）大～功（热衷于做大事，立大功，现常用以形容浮夸的作风）。\n(5)适于～光植物。带～荤。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喜"},{"id":"glyph-seal-559d","script":"seal","character":"喝","reading":"hē；hè；yè","description":"hē：(1)把液体饮料或流质食物咽下去～水。～酒。～茶。～粥。\n(2)特指喝酒～醉了。\nhè：大声喊叫～彩。～问。\nyè：声音嘶哑、噎塞儿生，号啼之声鸿朗高畅者寿，嘶～湿下者夭”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喝"},{"id":"glyph-seal-559f","script":"seal","character":"喟","reading":"kuì","description":"kuì：叹气的样子～然长叹。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喟"},{"id":"glyph-seal-55b7","script":"seal","character":"喷","reading":"pēn","description":"泉水自地下涌出;喷出,喷射\n马嘘气或鼓鼻\n扯→扯;闲扯\n⒈散着射出～泉。～ 火。～雾器。～气式飞机。\n⒈气味浓烈～香。\n⒉蔬菜、瓜果、鱼虾等上市的旺盛时期白菜～儿。鲜鱼正在～儿上。\n⒊量词，指开花结果实或成熟收割的次数头～棉花。收二～稻子了。\n喷fèn 1.吹奏。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喷"},{"id":"glyph-seal-55be","script":"seal","character":"喾","reading":"kù","description":"传说中的古代帝王名,即五帝之一的高辛氏","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-喾"},{"id":"glyph-seal-55c5","script":"seal","character":"嗅","reading":"xiù","description":"xiù：闻，用鼻子辨别气味～觉。～神经。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗅"},{"id":"glyph-seal-55cc","script":"seal","character":"嗌","reading":"ài；yì","description":"yì：咽喉。\nài：咽喉窒塞，噎。\n〔～～〕笑声，如一幸得胜，疾笑～～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗌"},{"id":"glyph-seal-55d1","script":"seal","character":"嗑","reading":"kē；kè","description":"kē：方言，话唠～儿。\nkè：(1)用上下门牙咬有壳的或硬的东西～瓜子儿。\n(2)闲谈，多话～牙。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗑"},{"id":"glyph-seal-55d4","script":"seal","character":"嗔","reading":"chēn","description":"chēn：(1)怒，生气～怒。～喝（hè）。～诟。～斥。～睨。\n(2)对人不满，怪罪～着。～怪。～责。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗔"},{"id":"glyph-seal-55dc","script":"seal","character":"嗜","reading":"shì","description":"嗜shì喜欢，特别爱好，爱好而成习惯～学。～酒。～好。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗜"},{"id":"glyph-seal-55de","script":"seal","character":"嗞","reading":"zī","description":"⒈像声词老鼠～ ～叫。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗞"},{"id":"glyph-seal-55df","script":"seal","character":"嗟","reading":"jiē","description":"jiē：文言叹词～乎。～叹。～来之食。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗟"},{"id":"glyph-seal-55e3","script":"seal","character":"嗣","reading":"sì","description":"sì：(1)接续，继承～后（以后）。～岁（来年）。～响（继承前人之业，如回声之相应）。～徽（继承先人的美德、声誉）。\n(2)子孙后～。～子。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗣"},{"id":"glyph-seal-55e5","script":"seal","character":"嗥","reading":"háo","description":"háo：野兽吼叫狼～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗥"},{"id":"glyph-seal-55f7","script":"seal","character":"嗷","reading":"áo","description":"áo：象声词，愁叹声，嘈杂声～～（哀号声）。～～待哺（形容饥饿时急于求食的样子）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗷"},{"id":"glyph-seal-55fe","script":"seal","character":"嗾","reading":"sǒu","description":"sǒu：指使狗的声音。\n〔～使〕教唆、指使别人做坏事。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嗾"},{"id":"glyph-seal-5609","script":"seal","character":"嘉","reading":"jiā","description":"jiā：(1)善，美～言。～宾。～言懿行。\n(2)夸奖，赞许～奖。～许。～勉。\n(3)吉庆，幸福～祥。～偶。\n(4)欢乐～会。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嘉"},{"id":"glyph-seal-560c","script":"seal","character":"嘌","reading":"piào；piāo","description":"piāo：疾速匪风飘兮，匪车～兮”。\n〔～呤〕有机化合物，无色结晶，在人体内气化而成尿酸。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嘌"},{"id":"glyph-seal-5618","script":"seal","character":"嘘","reading":"xū；shī","description":"xū：(1)慢慢地吐气，呵气～寒问暧。\n(2)叹气～唏（哭泣时抽噎）。仰天而～。\n(3)火或气的热力熏炙这点菜放到锅里～～。\nshī：叹词，表示反对，制止等～，别出声！","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嘘"},{"id":"glyph-seal-5624","script":"seal","character":"嘤","reading":"yīng","description":"哽塞;哽咽。多含有抽泣、哭鼻子之意\n嘤鸣\n嘤鸣相召\n嘤yīng鸟叫声鸟鸣～ ～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嘤"},{"id":"glyph-seal-5632","script":"seal","character":"嘲","reading":"cháo；zhāo","description":"cháo：讥笑，拿人取笑～笑。～弄。～骂。～诮。～谑。冷～热讽。\nzhāo：〔～哳（zhā）〕同啁哳”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嘲"},{"id":"glyph-seal-563f","script":"seal","character":"嘿","reading":"hēi；mò","description":"hēi：叹词（ａ．表示惊异或赞叹，如～，真不错！”ｂ．表示招呼或提醒，如～，注意点儿！”）。\n〔～～〕象声词，形容笑声。\nmò：同默”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嘿"},{"id":"glyph-seal-564d","script":"seal","character":"噍","reading":"jiào","description":"jiào：吃东西，嚼～类（尚生存的人）。倒（dǎo）～（反刍，亦作倒嚼”）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-噍"},{"id":"glyph-seal-564e","script":"seal","character":"噎","reading":"yē","description":"yē：(1)食物塞住了嗓子因～废食。～着了。\n(2)因为迎风而呼吸因难这风真～人。\n(3)说话顶撞人，使人无话可答他说话能把人～死。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-噎"},{"id":"glyph-seal-5664","script":"seal","character":"噤","reading":"jìn","description":"jìn：(1)闭口不说话～口。～声。～若寒蝉。\n(2)因寒冷而咬紧牙关或牙齿打战～战‘～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-噤"},{"id":"glyph-seal-5668","script":"seal","character":"器","reading":"qì","description":"qì：(1)用具的总称～皿。～物。～械。木～。武～。～小易盈。\n(2)生物体结构中具有某种独立生理机能的部分～官。消化～。\n(3)人的度量、才干～度。～量（liàng）。～宇。～质。大～晚成。\n(4)重视～重。～敬。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-器"},{"id":"glyph-seal-566a","script":"seal","character":"噪","reading":"zào","description":"zào：(1)许多鸟或虫子乱叫鹊～。蝉～。归鸟晚～。\n(2)声音杂乱～声。～音。～聒。\n(3)许多人大喊大叫，喧哗，鼓动～嚷。～聚。声名大～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-噪"},{"id":"glyph-seal-566b","script":"seal","character":"噫","reading":"yī","description":"yī：文言叹词，表示感慨、悲痛、叹息～！微斯人，吾谁与归”。～鸣。～嘻。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-噫"},{"id":"glyph-seal-566c","script":"seal","character":"噬","reading":"shì","description":"噬shì咬吞～。～脐莫及（用嘴咬肚脐，够不着。形容后悔已来不及了）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-噬"},{"id":"glyph-seal-5671","script":"seal","character":"噱","reading":"xué；jué","description":"jué：大笑。\nxué：笑～头。发～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-噱"},{"id":"glyph-seal-568e","script":"seal","character":"嚎","reading":"háo","description":"háo：大声叫或哭喊长～。鬼哭狼～。～啕（亦作号啕”）。～叫。～哭。～丧。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嚎"},{"id":"glyph-seal-568f","script":"seal","character":"嚏","reading":"tì","description":"tì：〔～喷〕鼻黏膜受到刺激而引起的一种猛烈带声的喷气现象（喷”读轻声）。亦称喷嚏”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嚏"},{"id":"glyph-seal-56a3","script":"seal","character":"嚣","reading":"xiāo","description":"害臊;害羞\n⒈喧哗，吵闹喧～。叫～。\n嚣áo 1.傲慢貌。参见\"嚣嚣\"。 2.忧愁貌;怨愁貌;怨恨貌。参见\"嚣然\"﹑\"嚣嚣\"。 3.谗毁貌。参见\"嚣嚣\"。 4.山凹之地。 5.古地名。 6.水名。 7.鸟名。 8.兽名\n，猴属。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嚣"},{"id":"glyph-seal-56bc","script":"seal","character":"嚼","reading":"jiáo；jué；jiào","description":"jiáo：用牙齿咬碎细～慢咽。味同～蜡。\njué：义同（一），用于某些复合词咀～。\njiào：〔倒（dǎo）～〕反刍，牛等动物把粗粗咀嚼后咽下去的食物再反回到嘴里细细咀嚼。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-嚼"},{"id":"glyph-seal-56ca","script":"seal","character":"囊","reading":"náng；nāng","description":"náng：(1)口袋药～。探～取物。～空如洗。～括。\n(2)像口袋的东西胆～。胶～。～肿。\n〔～生〕藏语，中国西藏农奴主家的奴隶。亦称朗生”。\nnāng：〔～膪〕猪的乳部肥而松软的肉。\n〔～揣〕ａ．虚弱，懦弱；ｂ．同囊膪”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-囊"},{"id":"glyph-seal-56da","script":"seal","character":"囚","reading":"qiú","description":"qiú：(1)拘禁～禁。～车。～牢。\n(2)被拘禁的人～犯。～徒。死～。～首垢面。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-囚"},{"id":"glyph-seal-56db","script":"seal","character":"四","reading":"sì","description":"sì：(1)数名，三加一（在钞票和单据上常用大写肆”代）～方。～边。～序（即四季”）。～体（ａ．指人的四肢；ｂ．指楷、草、隶、篆四种字体）。～库（古籍经、史、子、集四部的代称。亦称四部”）。～君子（中国画中对梅、兰、竹、菊四种花卉题材的总称）。\n(2)中国古代乐谱的记音符号，相当于简谱6”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-四"},{"id":"glyph-seal-56de","script":"seal","character":"回","reading":"huí","description":"⒈返，还，归～家乡。～祖国。～来吧。\n⒉答复，报答～音。～电。～报。\n⒊掉转，看过去，忆往昔～首。～顾。～忆。～心转意。\n⒋曲折，环绕，旋转～形针。峰～路转。巡～医疗。\n⒌量词两～事。他去了一～北京。\n⒍长篇小说的章节章～小说。第八～。\n①头朝后转～头看。\n②等一会儿～头再说。\n③回归，返回切莫一去不～头。\n④醒悟，改邪归正～头是岸。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-回"},{"id":"glyph-seal-56df","script":"seal","character":"囟","reading":"xìn","description":"xìn：〔～门〕婴儿头顶骨未合缝的地方。亦称囟脑门儿”、顶门儿”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-囟"},{"id":"glyph-seal-56e0","script":"seal","character":"因","reading":"yīn","description":"yīn：(1)原故，原由，事物发生前已具备的条件原～。～素。～果。病～。\n(2)理由～为（wéi）。～而。\n(3)依，顺着，沿袭～此。～之。～循（ａ．沿袭；ｂ．迟延拖拉）。～噎废食。陈陈相～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-因"},{"id":"glyph-seal-56e2","script":"seal","character":"团","reading":"tuán","description":"有点圆\n把东西揉弄成圆球形\n围绕\n聚集,集合\n⒈圆形～扇。\n⒉结成球形的东西。〈引〉堆饭～。面～儿。菜～子。毛线～。一～和气。\n⒊聚集，联合，集合～聚。～结。～圆。\n⒋有组织的集体剧～。儿童～。\n⒌中国共产主义青年团的简称她是～员。\n⒍军队的编制单位，它是师的下一级，营的上一级。\n⒎量词。用于成团的一～丝线。两～绳索。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-团"},{"id":"glyph-seal-56e4","script":"seal","character":"囤","reading":"dùn；tún","description":"dùn：用竹篾、荆条等编织成的或用席箔等围成的存放粮食等农产品的器物粮～。大～满，小～流。\ntún：储存，积存粮食货物～积（积聚贮存）。～集。～聚。～积居奇（指投机商人大量购存货物）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-囤"},{"id":"glyph-seal-56ed","script":"seal","character":"园","reading":"yuán","description":"园日涉以成趣。\n⒈种植蔬菜、花果等的地方菜～。桃～。花～儿。果～子。\n⒉供游玩、娱乐或保育等的地方公～。植物～。动物～。颐和～。游乐～。幼儿～。\n园wán 1.削除棱角使圆。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-园"},{"id":"glyph-seal-56f0","script":"seal","character":"困","reading":"kùn","description":"梱”的本字。门槛\n困〈形〉\n穷;贫困\n⒈穷苦，艰难贫～。～窘。排除～难。摆脱～境。\n⒉陷在艰难痛苦中～在深山老林。～兽犹斗。为病痛所～。〈引〉包围围～。把敌人～在碉堡里。\n⒊疲乏～倦。～乏。\n⒋〈方〉睡～觉。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-困"},{"id":"glyph-seal-56f1","script":"seal","character":"囱","reading":"cōng","description":"炉灶或锅炉等排出烟气的通道，如烟囱。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-56f4","script":"seal","character":"围","reading":"wéi","description":"包围\n⒈环绕，圈拦住～巾。～绕。～墙。～攻。包～。土～子。\n⒉四周四～。周～。外～。\n⒊量词。\n①两臂合抱的圆周长树大十～。\n②两手大拇指和食指合拢的圆周长腰大四～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-围"},{"id":"glyph-seal-56f9","script":"seal","character":"囹","reading":"líng","description":"líng：〔～圄〕监狱。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-囹"},{"id":"glyph-seal-56fa","script":"seal","character":"固","reading":"gù","description":"gù：(1)结实，牢靠坚～。稳～。巩～。凝～。加～。\n(2)坚定，不变动～执。～定。～本。\n(3)本，原来～有。～步自封（亦作故步自封”）。\n(4)鄙陋（见识浅少）。\n(5)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-固"},{"id":"glyph-seal-56fd","script":"seal","character":"国","reading":"guó","description":"周代,天子统治的是天下”,略等于现在说的全国”\n⒈国家爱～。～营。建设祖～。\n①它是一个或一些阶级压迫另外的阶级的工具，是暴力的机器。主要由军队、警察、法庭、监狱等组成。\n②一个国家独有的占领区域。\n⒉属于本国的～旗。～徽。～产品。\n⒊地区北～风光。\n⒋京城，首都～门。～都。\n⒌〈古〉我国诸侯或王侯的封地楚～。齐～。秦～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-国"},{"id":"glyph-seal-56fe","script":"seal","character":"图","reading":"tú","description":"图谋;谋取\n举其一不计其十,究其旧不图其\n⒈画画影～形。彩色～之。\n⒉用绘画表现出来的形象～画。～表。蓝～。插～。地～。\n⒊谋划，打算宏～。企～。\n⒋谋取，希望得到～谋。～强。～名～利。\n号叫\"图腾\"。有的氏族将图腾作为禁忌物，动、植物图腾则禁杀禁吃。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-图"},{"id":"glyph-seal-56ff","script":"seal","character":"囿","reading":"yòu","description":"yòu：(1)养动物的园子鹿～。园～。\n(2)局限，被限制～于成见。\n(3)借指事物萃聚之处游于六艺之～”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-囿"},{"id":"glyph-seal-5703","script":"seal","character":"圃","reading":"pǔ","description":"pǔ：(1)种植菜蔬、花草、瓜果的园子～田。菜～。花～。苗～。\n(2)指种植园圃的人吾不如老～”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圃"},{"id":"glyph-seal-5704","script":"seal","character":"圄","reading":"yǔ","description":"yǔ：〔囹～〕见囹”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圄"},{"id":"glyph-seal-5706","script":"seal","character":"圆","reading":"yuán","description":"圆通;灵活\n如今到外头去作官,自然非家居可比,总得学些\n⒈在平面上，定点和定距离的动点之轨迹的称谓。定点称\"～心\"。定距离称\"～的半径\"。有时也称轨迹所围的部分为～。称轨迹为～周。\n⒉像球形的滚～。～房顶。\n⒊完备，周全～满。大团～。\n⒋使完备，使周全～谎。自～其说。\n⒌婉转字正腔～。深～似转簧。\n⒍货币名。也作\"元\"一百～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圆"},{"id":"glyph-seal-5708","script":"seal","character":"圈","reading":"quān；juàn；juān","description":"quān：(1)环形，环形的东西圆～。花～。～套。画～。\n(2)周，周遭跑了一～儿。\n(3)范围势力～。\n(4)画环形～阅。～点。～定。\n(5)划界，围住～地。～闭。\njuàn：(1)养家畜的棚栏～舍（shè）。～养。～牢（饲养家畜的地方）。猪～。\n(2)姓。\njuān：关闭把鸡～起来。他已被～在监狱里。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圈"},{"id":"glyph-seal-5709","script":"seal","character":"圉","reading":"yǔ","description":"yǔ：(1)养马的地方～人。\n(2)边陲亦聊以固吾～也”。\n(3)防御其来不可～”。\n(4)同圄”。\n(5)古代乐器名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圉"},{"id":"glyph-seal-571c","script":"seal","character":"圜","reading":"huán；yuán","description":"huán：围绕转（zhuǎn）～。～流九十里。\nyuán：(1)同圆”。\n(2)指天体～则九重，孰营度之？”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圜"},{"id":"glyph-seal-571f","script":"seal","character":"土","reading":"tǔ","description":"tǔ：(1)地面上的泥沙混合物～壤。黄～。\n(2)疆域国～。领～。\n(3)本地的，地方性的故～。\n(4)民间生产的（区别于洋”）～方（民间流传的药方，亦称偏方”）。\n(5)不合潮流～气。\n(6)未熬制的鸦片烟～。\n(7)中国古代乐器八音之一。\n(8)中国少数民族，主要分布于青海省～族。\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-土"},{"id":"glyph-seal-5723","script":"seal","character":"圣","reading":"shèng","description":"聪明;才智胜人\n⒈伟大的，崇高的神～。革命～地。\n⒉在学问、技术等方面有特殊成就的人诗～。～手。\n⒊封建时代美化皇帝的说法～驾。～旨。\n⒋宗教徒称呼所崇拜的事物～经。～体。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圣"},{"id":"glyph-seal-5728","script":"seal","character":"在","reading":"zài","description":"zài：(1)存，居存～。健～。青春长～。\n(2)存留于某地点～家。～职。～位。\n(3)关于某方面，指出着重点～于（ａ．指出事物的本质所在，或指出事物以什么为内容；ｂ．决定于）。～乎。事～人为。\n(4)表示动作的进行他～种地。\n(5)介词，表示事情的时间、地点、情形、范围等～逃。～望。～握。～理。～朝（cháo）。～野。～世。\n(6)和所”连用，表示强调～所不辞。无所不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-在"},{"id":"glyph-seal-572a","script":"seal","character":"圪","reading":"gē","description":"gē：〔～垯〕ａ．小球形或块状的东西，如泥～～”；ｂ．小土丘，多用于地名（垯”均读轻声）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圪"},{"id":"glyph-seal-572c","script":"seal","character":"圬","reading":"wū","description":"wū：(1)泥瓦工人用的抹（mǒ）子。\n(2)抹（mò）墙。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圬"},{"id":"glyph-seal-572d","script":"seal","character":"圭","reading":"guī","description":"guī：(1)古代帝王或诸侯在举行典礼时拿的一种玉器，上圆（或剑头形）下方～角（jiǎo）（圭的棱角，喻锋芒）。\n(2)古代测日影的器具～表（ａ．测日影的器具；ｂ．标准）。～臬（指标准、法度，如奉为～～”）。\n(3)古代容量单位（一升的十万分之一）～撮（喻小量）。～勺。\n(4)古代重量单位，十圭重一铢，二十四铢重一两，十六两重一斤。\n(5)洁～田（古代卿大夫供祭祀用的田）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圭"},{"id":"glyph-seal-572e","script":"seal","character":"圮","reading":"pǐ","description":"pǐ：(1)塌坏，倒塌。\n(2)破裂，分裂是以悲痛，肝心～裂”。\n(3)毁灭，断绝分野殊异，遂用～绝，不图今日乃相得也”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圮"},{"id":"glyph-seal-572f","script":"seal","character":"圯","reading":"yí","description":"yí：桥。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圯"},{"id":"glyph-seal-5730","script":"seal","character":"地","reading":"dì；de","description":"dì：地面，大地；地方、地域。de：结构助词，连接状语和中心词，如认真地读书。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5739","script":"seal","character":"圹","reading":"kuàng","description":"原野\n通旷”。荒废\n敬谋无圹,敬事无圹,敬吏无圹,敬众无圹,敬敌无圹,夫是之\n⒈墓穴。\n⒉圹野，野外。\n⒊〈古〉通\"旷\"。荒废，历时久远。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圹"},{"id":"glyph-seal-573a","script":"seal","character":"场","reading":"chǎng","description":"祭坛旁的平地\n谷场,场子\n十月涤场。\n①平坦的空地。多用来翻晒粮食，碾轧谷物打谷～。\n②量词。用于事情的经过他得了一、大病，现在身体很弱。又见chǎng。\n①适合进行某种活动的比较大的地方会～、广～、商～。\n②舞台上～、下～、出～。\n③戏剧中较小的段落，每场表演故事的一个片断。\n④量词。用于文娱体育活动两～舞会、五～足球赛。\n⑤指某种活动领域官～。\n⑥电视接收机中，电子束对一幅画面的奇数行或偶数行完成一次隔行扫描，叫做一场。奇数场和偶数场合为一幅完整画面。\n⑦物质存在的一种基本形式。具有能量、动量和质量，能传递实物间的相互作用。如电场、磁场等。又见cháng。\n【场记】在摄影或摄像时，将现场拍摄的每个分镜头的内容作详细记录，以供继续拍摄或剪辑时参考和查对。\n【场景】\n①特指戏剧、电影中的场面。\n②泛指各种景象助人为乐的动人～。\n【场面描写】对在特定时间、地点里各类人物的活动进行总体面貌的描写，用以反映人与人之间的关系，揭示人物之间的矛盾冲突。\n⒈许多人聚集的、活动的或事情发生的地方～所。会～。市～。操～子。广～儿。现～。\n⒉舞台登～。出～。\n⒊戏剧的分段三幕六～。\n⒋量词。用于文娱、体育方面两～电影。三～足球赛。\n⒈平坦的空地，多用于晒、打粮食～院。打麦～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-场"},{"id":"glyph-seal-573b","script":"seal","character":"圻","reading":"qí；yín","description":"qí：(1)地的边长。\n(2)方千里之地今土数～而郢是城，不亦难乎”。\nyín：古同垠”，边际。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-圻"},{"id":"glyph-seal-5740","script":"seal","character":"址","reading":"zhǐ","description":"zhǐ：地基，地点住～。地～。旧～（ａ．过去的住址；ｂ．过去某个机构的建筑物所在的地址）。遗～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-址"},{"id":"glyph-seal-5742","script":"seal","character":"坂","reading":"bǎn","description":"bǎn：山坡，斜坡～上走丸（喻迅速）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坂"},{"id":"glyph-seal-5747","script":"seal","character":"均","reading":"jūn","description":"jūn：(1)平，匀，引申为调和～衡。势～力敌。平～。\n(2)皆，都，老少～安。\n(3)中国汉代计量单位，一均等于二千五百石。\n(4)古同韵”，和谐的声音。\n(5)古同钧”，造瓦器的转轮。\n〔～钟〕古代乐器。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-均"},{"id":"glyph-seal-574a","script":"seal","character":"坊","reading":"fāng；fáng","description":"fāng：(1)里巷（多用于街巷的名称）。\n(2)街市，市中店铺～间。街～（邻居）。\n(3)旧时标榜功德的建筑物牌～。节义～。\nfáng：(1)小手工业者的工作场所作～。\n(2)古同防”，防范。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坊"},{"id":"glyph-seal-574c","script":"seal","character":"坌","reading":"bèn","description":"bèn：(1)尘埃。\n(2)聚积。\n(3)粗劣。\n(4)古同笨”，蠢笨。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坌"},{"id":"glyph-seal-574e","script":"seal","character":"坎","reading":"kǎn","description":"kǎn：(1)低陷不平的地方，坑穴～井之蛙（喻知识浅陋的人）。～坷。\n(2)自然形成或人工修筑的台阶状东西土～。田～。\n(3)八卦之一，代表水。\n(4)指最紧要的地方或时机，当口儿这话可说到～儿上了。\n(5)指坏运气或被迫的处境今年是他的～儿。\n(6)同槛2”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坎"},{"id":"glyph-seal-574f","script":"seal","character":"坏","reading":"huài；pēi；pī；péi","description":"pēi：土丘千车拥孤隧，万马盘一～。”\n好；\npī：同坯”。\n好；\npéi：(1)古同培”，用泥土涂塞空隙。\n(2)古同培”，指屋的后墙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坏"},{"id":"glyph-seal-5750","script":"seal","character":"坐","reading":"zuò","description":"zuò：(1)古人双膝跪地，把臀部靠在脚后跟上，这是其本义，后泛指以臀部着物而止息席地而～。～待。～垫。～骨。～化（佛教指和尚盘膝坐着死去）。～禅。～功。～骑。\n(2)乘，搭～车。～船。\n(3)坚守，引申为常驻，不动楚人～其北门，而覆诸山下”。～庄。\n(4)建筑物的位置或背对着某一方向～落。～北朝南。\n(5)把锅、壶等放在火上～锅。\n(6)物体向后施压力房顶往后～。\n(7)介词，因，由于，为着停车～爱枫林晚，霜叶红于二月花”。\n(8)副词（ａ．空，徒然，如胡为～自苦，吞悲仍抚膺”；ｂ．无故，自然而然，如如若此，则盐必～长十倍”；ｃ．遂，即将，如寒英～销落，何用慰远客”；ｄ．深，如感此伤妾心，～愁红颜老”；ｅ．正，恰好，如西村渡口人烟晚，～见渔舟两两归”）。\n(9)定罪连～。反～。～赃（犯贪脏罪）。\n(10)瓜果等植物结实～瓜。～果。\n(11)同座”①。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坐"},{"id":"glyph-seal-5751","script":"seal","character":"坑","reading":"kēng","description":"kēng：(1)洼下去的地方～洼。火～（喻悲惨的生活环境）。\n(2)把人活埋～杀。焚书～儒。\n(3)陷害，设计使人受到损失～害。～骗。\n(4)地洞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坑"},{"id":"glyph-seal-5757","script":"seal","character":"块","reading":"kuài","description":"⒈成片、团或疙瘩状的东西土～儿。石～儿。煤～儿。～根。～茎。\n⒉〈古〉孤独～独。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-块"},{"id":"glyph-seal-575a","script":"seal","character":"坚","reading":"jiān","description":"⒈硬，结实，牢固～硬。结构～固。～不可摧。〈引〉不动摇，决不改变更～决。意志～强。～持到底。～守阵地。～贞不屈。\n⒉牢固的，艰难的～冰。攻～不畏难。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坚"},{"id":"glyph-seal-575b","script":"seal","character":"坛","reading":"tán","description":"像坛之物\n⒊壇、\n⒋壜、\n⒋罎、\n⒈〈古〉用于盟誓、祭祀等的土筑高台或建筑物为～而盟。天～。登～拜将。\n⒉庭院中的土台花～。〈引〉庭院腐鼠在～。\n⒊指文艺、体育界或舆论阵地文～。球～。讲～。论～。\n⒋肚大口小的一种陶器酒～子。泡菜～。\n坛dàn 1.平坦。\n坛shàn 1.厅堂。 2.庭院。 3.通\"墠\"。清除土地。亦泛指清除。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坛"},{"id":"glyph-seal-575f","script":"seal","character":"坟","reading":"fén","description":"注或曰河坟,汝坟、淮坟也。”\n土堆\n通濆”。水边;沿河的高地\n⒈埋葬死人以后垒起的土堆～墓。\n坟fèn 1.土质肥沃。 2.高起。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坟"},{"id":"glyph-seal-5760","script":"seal","character":"坠","reading":"zhuì","description":"剑之所从坠。\n⒈落，掉下，下沉～落。～下。天欲～。船锚正在下～。\n⒉系在物体上的垂着之东西扇～儿。耳～子。\n①耳坠。\n②河南、山东等地的一种曲艺河南～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坠"},{"id":"glyph-seal-5761","script":"seal","character":"坡","reading":"pō","description":"pō：(1)倾斜的地方山～。下～。\n(2)倾斜～道。～降（jiàng）（ａ．坡；ｂ．坡度）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坡"},{"id":"glyph-seal-5764","script":"seal","character":"坤","reading":"kūn","description":"kūn：(1)八卦之一乾（qián）～。～舆。\n(2)称女性的～造。～宅（旧时婚礼称女家）。～表。～车。～鞋。～角儿（juér）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坤"},{"id":"glyph-seal-5766","script":"seal","character":"坦","reading":"tǎn","description":"tǎn：(1)宽而平平～。～荡。～直（ａ．平坦笔直；ｂ．坦率）。～途。\n(2)心地平静，没有隐瞒～白。～然。～挚。～诚。～率（shuài）。\n(3)坦腹”的简称，指女婿～床。令～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坦"},{"id":"glyph-seal-576a","script":"seal","character":"坪","reading":"píng","description":"píng：平坦的场地草～。地～。～坝。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坪"},{"id":"glyph-seal-576b","script":"seal","character":"坫","reading":"diàn","description":"diàn：(1)屏障。\n(2)古代屋中的土台子，上面可放饮食用具。\n(3)边界垓～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坫"},{"id":"glyph-seal-576d","script":"seal","character":"坭","reading":"ní","description":"ní：(1)同泥”红毛～（方言，水泥）。\n(2)地名用字白～（在中国广东省）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坭"},{"id":"glyph-seal-576f","script":"seal","character":"坯","reading":"pī","description":"pī：(1)没有烧过的砖瓦、陶器等土～。砖～。打～。脱～。\n(2)泛指半成品钢～。～布。毛～。\n(3)用以指未成年的人好～子。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坯"},{"id":"glyph-seal-5773","script":"seal","character":"坳","reading":"ào","description":"ào：山间的平地山～。～口（山或丘陵间的较低处，多为穿过山岭的通道）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坳"},{"id":"glyph-seal-5777","script":"seal","character":"坷","reading":"kě；kē","description":"kē：〔～垃〕方言，土块。（垃”读轻声）。\nkě：〔坎～〕见坎”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坷"},{"id":"glyph-seal-577b","script":"seal","character":"坻","reading":"dǐ；chí","description":"dǐ：高坡地坂～。\nchí：水中的小块高地～京（京”，高丘，形容丰年堆积如山的谷物）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坻"},{"id":"glyph-seal-577c","script":"seal","character":"坼","reading":"chè","description":"chè：裂开干～。～裂。天旱地～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-坼"},{"id":"glyph-seal-5782","script":"seal","character":"垂","reading":"chuí","description":"chuí：(1)东西一头挂下～杨柳。～钓。～直。～线。～手（ａ．表示容易；ｂ．表示恭敬）。～泪。～髫（头发下垂，指儿童）。～头丧气。\n(2)敬辞，用于别人（多是长辈或上级）对自己的行动～爱。～怜。～询。\n(3)传下去，传留后世～范。永～不朽。\n(4)接近，快要～危。～老。～成。功败～成。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垂"},{"id":"glyph-seal-5784","script":"seal","character":"垄","reading":"lǒng","description":"土埂\n田埂\n成行种植农作物的土埂\n高丘,高地\n⒈田埂，也指田间的高地～土。\n⒉农作物的行或行间的土埂麦～。田～。\n⒊像垄的东西瓦～。\n⒋坟墓丘～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垄"},{"id":"glyph-seal-5786","script":"seal","character":"垆","reading":"lú","description":"黑色坚实的土壤\n通罏”。古时酒店里安放酒瓮的土台子\n借指酒店\n垆坶\n垆埴\n⒈黑色坚硬的土。\n⒉酒店里放置酒坛的土台子。也指酒店。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垆"},{"id":"glyph-seal-578b","script":"seal","character":"型","reading":"xíng","description":"xíng：(1)铸造器物用的模子砂～。～砂（制造砂型的材料）。\n(2)样式类～。新～。～号。脸～。血～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-型"},{"id":"glyph-seal-5792","script":"seal","character":"垒","reading":"lěi","description":"棒球内场的一个垒\n⒈〈古〉军营中作防守用的墙壁或建筑物营～。高～深沟。\n⒉堆，砌～墙壁。～猪圈。\n垒léi 1.巨大。 2.重叠累积的样子。参见\"垒垒\"。 3.通\"累\"。捆绑。\n垒lèi 1.见\"垒石\"。\n垒lǜ 1.见\"郁垒\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垒"},{"id":"glyph-seal-5793","script":"seal","character":"垓","reading":"gāi","description":"gāi：(1)荒远之地，一方广大区域～埏（极远的地方）。天子居九～之田”。～极（荒远之外）。\n(2)界限～坫（边界）。重（chóng）垠累（lěi）～（重重的限制）。\n(3)古代数名，指一万万。\n(4)古同陔”，层，阶次。\n(5)指战场、陆地～心（战地中心）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垓"},{"id":"glyph-seal-579b","script":"seal","character":"垛","reading":"duǒ；duò","description":"duǒ：(1)墙或某些建筑物突出的部分，有支撑或掩蔽作用～子。～堞（城墙上凹凸状矮墙，即女儿墙”）。城～。\n(2)土筑的箭靶子箭～。射～。中（zhòng）～。\nduò：(1)整齐地堆积起来～积。堆～。\n(2)整齐地堆积成的堆麦～。草～。\n(3)量词，用于堆砌起来的东西一～墙。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垛"},{"id":"glyph-seal-57a0","script":"seal","character":"垠","reading":"yín","description":"yín：边，岸，界限～际。一望无～∑大无～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垠"},{"id":"glyph-seal-57a2","script":"seal","character":"垢","reading":"gòu","description":"gòu：(1)污秽，脏东西污～。泥～。牙～。～腻。～秽。～敝（又脏又破）。\n(2)同诟”。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垢"},{"id":"glyph-seal-57a3","script":"seal","character":"垣","reading":"yuán","description":"yuán：(1)矮墙，墙短～。城～。墙～。\n(2)城省～（省城）。\n(3)官署谏～（谏官官署）。\n(4)星的区域，古代把众星分为上、中、下三垣。\n(5)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垣"},{"id":"glyph-seal-57a4","script":"seal","character":"垤","reading":"dié","description":"dié：(1)蚂蚁做窝时堆在洞口的土蚁～。\n(2)小土丘丘～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垤"},{"id":"glyph-seal-57a6","script":"seal","character":"垦","reading":"kěn","description":"损伤","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垦"},{"id":"glyph-seal-57a9","script":"seal","character":"垩","reading":"è","description":"用白色涂料粉刷墙壁\n②\"堊\"的简化字。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垩"},{"id":"glyph-seal-57ab","script":"seal","character":"垫","reading":"diàn","description":"用别的东西衬在下面,使物加高、加厚或起隔离作用\n①在主体物件上面或底下铺放一些东西，使加高、加厚或平整～桌子、～上褥子、把路～平。\n②专供铺放的东西鞋～、座～。\n③替人暂付款项～钱。\n【垫脚石】比喻借用来向上爬的人或事物。\n【垫球】排球运动基本技术之一。两臂自然伸直相靠，两手相并，虎口向上，伸出垫击球。控制面积大，起球效果好。\n【垫圈】垫在螺母与被连接件之间的零件。\n【垫支资本】见【预付总资本】。\n垫dié 1.垫江，古县名。在今四川省合川县。 2.垫江，今县名。在四川省东部。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-垫"},{"id":"glyph-seal-57b8","script":"seal","character":"垸","reading":"yuàn","description":"江河、湖泊附近用堤围起来、用于挡水护田的区域或设施。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-57c2","script":"seal","character":"埂","reading":"gěng","description":"gěng：(1)田间稍稍高起的小路田～儿。\n(2)地势高起的长条地方山～。\n(3)用泥土筑起的堤防～堰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-埂"},{"id":"glyph-seal-57c3","script":"seal","character":"埃","reading":"āi","description":"āi：(1)灰尘尘～。\n(2)公制长度单位，一万万分之一厘米，常用以表示光波的波长及其他微小长度。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-埃"},{"id":"glyph-seal-57ce","script":"seal","character":"城","reading":"chéng","description":"chéng：(1)围绕都市的高墙～墙。～池。～圈。～郭（城”指内城墙，郭”指外城墙）。～楼。～堞（城上的矮墙，亦称女儿墙”）。～垛。\n(2)都市～市。～镇。～府（ａ．城市及官署；ｂ．喻待人处世的心机，如胸无～～”）。～邑。～乡。～建。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-城"},{"id":"glyph-seal-57d2","script":"seal","character":"埒","reading":"liè","description":"liè：(1)矮墙，场地四周的土围墙。\n(2)等同故吴诸侯也，以即山铸钱，富～天子。”\n(3)田塍。\n(4)涯际；界限休息于无委曲之隅，而游敖于无形～之野。”\n(5)山上的水流。\n(6)古度量名。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-埒"},{"id":"glyph-seal-57d8","script":"seal","character":"埘","reading":"shí","description":"埘（塸）shí〈古〉指鸡窝。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-埘"},{"id":"glyph-seal-57d9","script":"seal","character":"埙","reading":"xūn","description":"、骨、象牙制成的","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-埙"},{"id":"glyph-seal-57df","script":"seal","character":"域","reading":"yù","description":"yù：在一定疆界内的地方～外。异～。区～。地～。领～。疆～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-域"},{"id":"glyph-seal-57e4","script":"seal","character":"埤","reading":"pí；pì","description":"pí：增加～益。\npì：〔～堄〕城上矮墙。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-埤"},{"id":"glyph-seal-57f4","script":"seal","character":"埴","reading":"zhí","description":"zhí：黏土。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-埴"},{"id":"glyph-seal-57f5","script":"seal","character":"埵","reading":"duǒ","description":"埵duǒ 1.土堆。 2.堤防。参见\"埵防\"。 3.风箱的出风铁管。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-埵"},{"id":"glyph-seal-57f8","script":"seal","character":"埸","reading":"yì","description":"yì：(1)田界。\n(2)疆界，边境疆～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-埸"},{"id":"glyph-seal-57f9","script":"seal","character":"培","reading":"péi","description":"péi：(1)为保护植物或墙堤等，在根基部分加土～土。～种（zhòng）。～修。～植。\n(2)帮助和保护人的成长～养。～育。～训。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-培"},{"id":"glyph-seal-57fa","script":"seal","character":"基","reading":"jī","description":"jī：(1)建筑物的根脚～石。～础。奠～。\n(2)根本的，起始的～本。～业。～层。～点。～准。\n(3)根据～于。\n(4)化学上化合物的分子中所含的一部分子原子被看作是一个单位时，称作基”～团。～态。氨～。羧～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-基"},{"id":"glyph-seal-57fd","script":"seal","character":"埽","reading":"sào","description":"治河防水时用枝条、秸秆、石土等捆成的材料；也指用这类材料修成的河工建筑。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-5802","script":"seal","character":"堂","reading":"táng","description":"táng：(1)正房，高大的房子～屋。～客。～倌。礼～。澡～。\n(2)同祖父的亲属关系～房。～兄弟。\n(3)旧时官吏审案办事的地方大～。公～。过～。\n(4)量词上了一～课。一～家具。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-堂"},{"id":"glyph-seal-5807","script":"seal","character":"堇","reading":"jǐn；jīn","description":"jīn：〔～菜〕多年生草本植物，茎细弱，叶呈肾脏形，边缘有锯齿，春末开白花，有紫色条纹。果实椭圆形，全草可入药，亦称堇堇菜”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-堇"},{"id":"glyph-seal-580b","script":"seal","character":"堋","reading":"péng；bèng","description":"péng：(1)分水堤（中国战国时李冰修建都江堰时所创建）。\n(2)射击瞄准用的土墙。\nbèng：丧葬下土。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-堋"},{"id":"glyph-seal-5811","script":"seal","character":"堑","reading":"qiàn","description":"挫折\n挖掘\n⒈壕沟，护城河深～。沟～。天～变通途。\n⒉陷坑。〈喻〉挫折，吃亏吃一～，长一智。\n⒊挖沟环而～之。\n堑jiàn 1.低下。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-堑"},{"id":"glyph-seal-5819","script":"seal","character":"堙","reading":"yīn","description":"yīn：(1)堵塞～窒。～郁（闷塞，气郁结不畅）。\n(2)堆成的土山距～（古代攻城时，积土为山，然后登堙观察城里敌情）。\n(3)古同湮”，埋没。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-堙"},{"id":"glyph-seal-5824","script":"seal","character":"堤","reading":"dī","description":"dī：用土石等材料修筑的挡水的高岸河～。～。～岸。～坝。～防。～堰。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-堤"},{"id":"glyph-seal-582a","script":"seal","character":"堪","reading":"kān","description":"kān：(1)能，可以，足以不～设想。～当重任。～以告慰。\n(2)忍受，能支持难～。不～一击。狼狈不～。疲惫不～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-堪"},{"id":"glyph-seal-5835","script":"seal","character":"堵","reading":"dǔ","description":"dǔ：(1)阻塞（sè），挡～塞。～挡。～截。～击。～嘴。\n(2)心中不畅快～心。\n(3)墙围者如～。\n(4)量词，用于墙。\n(5)古代钟或磐十六枚编成一组，挂在一个架子上称一堵”。\n(6)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-堵"},{"id":"glyph-seal-584d","script":"seal","character":"塍","reading":"chéng","description":"chéng：田间的土埂子，小堤。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-塍"},{"id":"glyph-seal-5854","script":"seal","character":"塔","reading":"tǎ","description":"tǎ：(1)佛教特有的高耸的建筑物，尖顶，多层，常有七级、九级、十三级等，形状有圆形的、多角形的，一般用以藏舍利、经卷等宝～。佛～。\n(2)像塔形的建筑物或器物水～。灯～。纪念～。金字～。～楼。\n(3)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-塔"},{"id":"glyph-seal-5858","script":"seal","character":"塘","reading":"táng","description":"táng：(1)堤岸，堤防～坝。～堰∮～。～。\n(2)水池池～∩～。鱼～。苇～。\n(3)某些地区在室内挖小坑用来生火火～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-塘"},{"id":"glyph-seal-585e","script":"seal","character":"塞","reading":"sāi；sài；sè","description":"sāi：(1)堵，填满空隙堵～漏洞。～尺。～规。\n(2)堵住器物口的东西活～。～子。\nsài：边界上险要地方要～。关～。～外。边～。～翁失马。\nsè：义同（一）①，用于若干书面语词闭～。阻～。搪～。～责。顿开茅～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-塞"},{"id":"glyph-seal-586b","script":"seal","character":"填","reading":"tián；zhèn","description":"tián：(1)把空缺的地方塞满或补满～塞。～补。～充。～空（kòng）。义愤～膺。\n(2)在空白表格上按项目写～表。～词。\n(3)形容声音巨大～然。\n挖；\nzhèn：古同镇”，使安定。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-填"},{"id":"glyph-seal-587e","script":"seal","character":"塾","reading":"shú","description":"shú：(1)旧时私人设立的教学的地方～师。家～。私～。\n(2)古代指门内东西两侧的堂屋。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-塾"},{"id":"glyph-seal-5880","script":"seal","character":"墀","reading":"chí","description":"chí：台阶上的空地，亦指台阶丹～（用红漆涂的台阶）。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-墀"},{"id":"glyph-seal-5883","script":"seal","character":"境","reading":"jìng","description":"jìng：(1)疆界，边界～界。国～。入～。出～。边～。\n(2)地方，区域，处所无人之～。佳～。环～。身临其～。\n(3)状况，地步～况。顺～。逆～。困～。事过～迁。～遇。意～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-境"},{"id":"glyph-seal-5889","script":"seal","character":"墉","reading":"yōng","description":"yōng：(1)城墙～垣。\n(2)高墙谁谓鼠无牙？何以穿我～！”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-墉"},{"id":"glyph-seal-5893","script":"seal","character":"墓","reading":"mù","description":"mù：埋葬死人的地方～穴。～地。～园。～道。～碑。坟～。～志铭。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-墓"},{"id":"glyph-seal-5899","script":"seal","character":"墙","reading":"qiáng","description":"门屏","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-墙"},{"id":"glyph-seal-589e","script":"seal","character":"增","reading":"zēng","description":"zēng：加多，添～加。～多。～添。～益。～生（ａ．同增殖”；ｂ．古代科举制度中生员名目之一）。～产。～长（zhǎng）。～援。～殖。～辉。～减。～删。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-增"},{"id":"glyph-seal-58a8","script":"seal","character":"墨","reading":"mò","description":"mò：(1)写字绘画用的黑色颜料一锭～。～汁。～盒。～迹。～宝（珍贵的字画。亦用来尊称别人写的字、画的画）。\n(2)写字画画用的各色颜料～水。油～。粉～登场。\n(3)黑色或接近于黑色的～黑。～面（ａ．黑的脸色；ｂ．指墨刑）。～镜。～绿。～菊。～晶（黑色的水晶）。\n(4)贪污贪～。～吏。\n(5)古代一种刑罚，在脸上刺字并涂墨（亦称黥”）～刑。\n(6)姓。\n(7)古同默”，缄默。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-墨"},{"id":"glyph-seal-58bc","script":"seal","character":"墼","reading":"jī","description":"jī：(1)未烧的砖坯土～。\n(2)粉末加水做成的块状物炭～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-墼"},{"id":"glyph-seal-58c1","script":"seal","character":"壁","reading":"bì","description":"bì：(1)墙四～。～报。～画。～挂。～毯。～橱。～灯。铜墙铁～。\n(2)指某些物体内部的表层胃～。肠～。\n(3)陡削的山崖峭～。～立。\n(4)军营的围墙～垒。坚～清野。作～上观（坐观双方成败，不帮助任何一方）。\n(5)星名，二十八宿之一。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-壁"},{"id":"glyph-seal-58e4","script":"seal","character":"壤","reading":"rǎng","description":"rǎng：(1)松软的土，可耕之地土～。沃～。～土。\n(2)地，与天”相对霄～。天～之别。\n(3)地区，区域～界。接～。穷乡僻～。\n(4)古同攘”，纷乱。\n(5)古同穰”，五谷丰收。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-壤"},{"id":"glyph-seal-58eb","script":"seal","character":"士","reading":"shì","description":"shì：(1)古代统治阶级中次于卿大夫的一个阶层～族。～大夫。\n(2)旧时指读书人～子。～民。学～。\n(3)未婚的男子，泛指男子～女。\n(4)对人的美称志～。烈～。女～。\n(5)军衔的一级，在尉以下；亦泛指军人；上～。～兵。～卒。～气。\n(6)称某些专业人员医～。护～。\n(7)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-士"},{"id":"glyph-seal-58ec","script":"seal","character":"壬","reading":"rén","description":"rén：(1)天干的第九位，用作顺序第九的代称。\n(2)姓。\n〔～人〕巧言谄媚的人。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-壬"},{"id":"glyph-seal-58ee","script":"seal","character":"壮","reading":"zhuàng","description":"⒈强健，有力强～。健～。年青力～√苗～。\n⒉雄伟，宏伟，有气魄雄～。～丽。～观。～志。～烈。气～山河。\n⒊增大，加强～大。他为你～胆。\n壮qiāng 1.伤。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-壮"},{"id":"glyph-seal-58f0","script":"seal","character":"声","reading":"shēng","description":"⒈物体振动时所产生的能引起听觉的波～波。～音。说话～。金石之～。\n⒉名誉，名望名～。～誉。～价。～望。～威。\n⒊宣称，说出，扬言～称。～明。～张。～罪致讨。～东击西。\n⒋量词大喊三～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-声"},{"id":"glyph-seal-58f6","script":"seal","character":"壶","reading":"hú","description":"盛水、茶或酒等的器具，常有嘴、把和盖。","enabled":true,"collection":"常用汉字","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-58f9","script":"seal","character":"壹","reading":"yī","description":"yī：一”的大写。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-壹"},{"id":"glyph-seal-5904","script":"seal","character":"处","reading":"chǔ","description":"居住;生活\n①居住穴居野～。\n②与别人一起生活；交往他这个人很好～。\n③存在；居我们国家正～于一个伟大的变革时期。\n④处置；办理～分、～理。又见chù。\n【处方】医生给病人开的药方。包括开方日期、病人姓名、年龄、性别、药名、数量、剂型、用法、用量等。\n【处决】指执行死刑。\n【处女】\n①未婚女子。又叫处子。\n【处女膜】女性阴道口周围的一层薄膜，有不规则的小孔。经性交或受到外伤后破裂。\n【处士】古时称有德才，但不愿做官而隐居的人◇来泛指没有做过官的读书人。\n【处之泰然】像平常一样对待，好像没事一样。指对待困难或意外情况沉着镇静。也指对某些应当在意的事毫不在意。泰然不以为意、若无其事的样子。又作泰然处之。\n【处子】见【处女】\n①地方～所。\n②机关或机关中的一个部门人事～、保卫～。又见chǔ。\n⒈居住久～农村。\n⒉存，置～在。～于。～心积虑。设身～地。\n⒊交往，同在一起和睦相～。\n⒋安排，解决，办理～置。～理。～之泰然。\n⒌罚，惩办～分。～决。惩～。判～。\n⒈地方，位置～所。全国各～。〈引〉点，部分好～。坏～。益～。短～。\n⒉机关单位或其中的部门政工～。卫生～。教务～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-处"},{"id":"glyph-seal-5907","script":"seal","character":"备","reading":"bèi","description":"完备;齐备\n①具有德才兼～。\n②准备～课。#防备～战。\n④完全关怀～至。\n【备忘录】\n①外交文书。声明自己方面对某问题的立场，或把某些事项的概况通知对方。\n②随时记载，帮助记忆的笔记本。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-备"},{"id":"glyph-seal-590d","script":"seal","character":"复","reading":"fù","description":"死者不可復生。\n⒈返，回去往～。至今五十年而不～。\n⒉回答，回报～命。～信。报～。～仇。\n⒊还原，使回归恢～。～原。～员军人。\n⒌重叠，繁多的，不是单一的～杂。～层。～句。重～。山重水～疑无路。～式立交桥。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-复"},{"id":"glyph-seal-590f","script":"seal","character":"夏","reading":"xià","description":"xià：(1)一年的第二季～季。～天。～令。～播。～熟。～粮。\n(2)中国朝代名～代。～历。\n(3)指中国华～。\n(4)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夏"},{"id":"glyph-seal-5914","script":"seal","character":"夔","reading":"kuí","description":"kuí：古代传说中的一种龙形异兽。\n〔～～〕敬谨恐惧的样子。\n〔～立〕肃立。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夔"},{"id":"glyph-seal-5915","script":"seal","character":"夕","reading":"xī","description":"xī：(1)日落的时候～阳。～照。朝（zhāo）～相处（chǔ）。\n(2)泛指晚上前～。除～。一～谈。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夕"},{"id":"glyph-seal-5916","script":"seal","character":"外","reading":"wài","description":"wài：(1)与内”、里”相对～边。～因。里应（yìng）～合。～行（háng）。\n(2)不是自己这方面的～国。～路（同外地”）。～族。～省。～星人。\n(3)指外国”～域。～宾。～商。\n(4)称母亲、姐妹或女儿方面的亲戚～公。～婆。～甥。\n(5)称岳父母～父。～姑（岳母）。\n(6)称丈夫～子（亦指非婚生之子）。\n(7)关系疏远的～人。\n(8)对正式的而言，指非正式的～号（绰号）。～史（指正史以外的野史、杂史和以叙述人物为主的旧小说）。～传（zhuàn）。\n(9)传统戏剧角色名～旦。～末。～净。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-外"},{"id":"glyph-seal-5919","script":"seal","character":"夙","reading":"sù","description":"sù：(1)早～夜。～兴（xīng）夜寐。\n(2)素有的，旧有的～日。～怨。～愿。～志。～敌。～诺。～嫌。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夙"},{"id":"glyph-seal-591a","script":"seal","character":"多","reading":"duō","description":"duō：(1)数量大，与少”、寡”相对人～。～年。～姿。～层次。～角度。～难（nàn）兴（xīng）邦。～～益善。～行不义必自毙。\n(2)数目在二以上～年生草。～项式。～义词。～元论。\n(3)有余，比一定的数目大～余。一年～。\n(4)过分，不必要的～嘴。～心。～此一举。\n(5)相差的程度大好得～。\n(6)表示惊异、赞叹～好。\n(7)表示某种程度有～大劲儿使～大劲儿。\n(8)表疑问有～大呢？～会儿？\n(9)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-多"},{"id":"glyph-seal-591c","script":"seal","character":"夜","reading":"yè","description":"yè：天黑的时间，与日”或昼”相对～晚。日日～～。～阑（夜将尽时）。～盲。～幕。～宵。～话。～袭。～行（xíng）。～战。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夜"},{"id":"glyph-seal-591f","script":"seal","character":"够","reading":"gòu","description":"gòu：(1)满足一定的限度～用。～数。～本。足～。能～。～朋友。\n(2)腻，厌烦听～了。\n(3)达到，及～格。～得着。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-够"},{"id":"glyph-seal-5924","script":"seal","character":"夤","reading":"yín","description":"yín：(1)深～夜。\n(2)敬畏。\n〔～缘〕攀缘上升，喻拉拢关系，向上巴结。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夤"},{"id":"glyph-seal-5927","script":"seal","character":"大","reading":"dà","description":"形容体积、面积、数量、力量、规模、程度等方面超过一般或超过所比较的对象。与小”相对","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-大"},{"id":"glyph-seal-5929","script":"seal","character":"天","reading":"tiān","description":"天空，与大地相对。","enabled":true,"collection":"常用汉字","source":"原有内置文字简注；汉字按常用义说明，彝藏文字按音节或字母名说明。"},{"id":"glyph-seal-592a","script":"seal","character":"太","reading":"tài","description":"tài：(1)过于～长。\n(2)极端，最～甚。～平。\n(3)高，大～空。～学。\n(4)很不～好。\n(5)身分最高或辈分更高的～老伯。～夫人（旧时尊称别人的母亲）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-太"},{"id":"glyph-seal-592b","script":"seal","character":"夫","reading":"fū；fú","description":"fū：(1)旧时称成年男子渔～。农～。万～不当之勇。\n(2)旧时称服劳役的人～役。拉～。\n(3)与妻结成配偶者丈～。～妇。\n〔～子〕ａ．旧时对学者的称呼；ｂ．旧时称老师；ｃ．旧时妻称夫；ｄ．称读古书而思想陈腐的人。\n妇；妻；\nfú：(1)文言发语词～天地者。\n(2)文言助词逝者如斯～。\n(3)文言指示代词，相当于这”或那”～猫至。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夫"},{"id":"glyph-seal-592c","script":"seal","character":"夬","reading":"guài","description":"决断；《周易》六十四卦之一，为夬卦。","enabled":true,"collection":"篆字扩展","source":"矩阵回声编者简注（常用义）"},{"id":"glyph-seal-592d","script":"seal","character":"夭","reading":"yāo","description":"yāo：(1)草木茂盛美丽～～（ａ．茂盛而美丽，如桃之～～”；ｂ．颜色和悦的样子，如～～如也”；ｃ．灾）。\n(2)未成年的人死去～折。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夭"},{"id":"glyph-seal-592e","script":"seal","character":"央","reading":"yāng","description":"yāng：(1)中心，正当中中～。\n(2)恳求～求。～告。\n(3)尽，完了夜未～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-央"},{"id":"glyph-seal-5931","script":"seal","character":"失","reading":"shī","description":"shī：(1)丢遗～。坐～良机。收复～地。流离～所。\n(2)违背～约。～信。\n(3)找不着迷～方向。\n(4)没有掌握住～言。～职。～调（tiáo）。\n(5)没有达到～望。～意。\n(6)错误～误。～策。过～。～之毫厘，谬以千里。\n(7)改变常态惊慌～色。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-失"},{"id":"glyph-seal-5934","script":"seal","character":"头","reading":"tóu","description":"将子头与剑来。\n低头思故乡。\n⒈脑袋，人体的最上部分或动物体的最前部分～颅。特指头发梳～。\n⒉物体的顶端、前端或事情的起点、终点山～。车～。有～有尾。一年到～。\n⒊第一，开初的～号。～班。～等舱。～半月。\n⒋以前，在前面的～三年。～里走的是她。\n⒍方面他们几个是一～的。\n⒎接近事到临～。\n⒏物品的残存部分粉笔～。布～儿。\n⒐量词。指牲畜、像头的、不定数量等五～猪。四～蒜。百来～。\n①脑筋，理智或思想不要昏～昏脑。\n②要领，门路这件事还没有摸着～脑。\n③首领她是这儿的～脑。\n头tou 1.名词后缀。接于名词性词根之后。 2.名词后缀。接于动词词根之后。 3.名词后缀。接于形容词词根之后。 4.方位词后缀。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-头"},{"id":"glyph-seal-5937","script":"seal","character":"夷","reading":"yí","description":"yí：(1)中国古代称东部的民族东～。九～（古时称东夷有九种）。\n(2)中国旧时指外国或外国的华～杂处（chǔ）。\n(3)平，平坦，平安化险为～。\n(4)弄平～为平地。\n(5)消灭～灭。族～（诛杀犯罪者家族）。\n(6)等辈诸将皆陛下故等～”。\n(7)古代的锄类工具。\n(8)古同怡”，喜悦。\n(9)古同痍”，创伤。\n(10)姓。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夷"},{"id":"glyph-seal-5938","script":"seal","character":"夸","reading":"kuā","description":"通說”。自大;炫耀\n⒈说大话～大其词。～下海口。过于～张。～耀自己。～ ～其谈。\n⒉赞赏，颂扬～奖∶人好事有人～。\n夸kuà 1.跨越。 2.引申为超过。参见\"夸迈\"。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夸"},{"id":"glyph-seal-5939","script":"seal","character":"夹","reading":"jiā","description":"栽插在物体的两边\n带;沿靠\n⒉见jiā。\n⒈双层的衣物～衣。～棉被。\n⒉\"袷\"另见qiā。\n⒈在两旁，在两面～攻。～击。\n⒉从两旁把东西钳住～起来。～着书包。手指～着钢笔。〈引〉两旁有东西限制住～缝。～道相逢。\n⒊混杂，搀杂～杂。雨～雪。\n⒋夹东西的用具发～子。讲义～。食品～儿。\n夹xiá 1.窄。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夹"},{"id":"glyph-seal-593a","script":"seal","character":"夺","reading":"duó","description":"强取\n①强取。\n②争取得到～标。\n③使失去剥～。\n④做决定定～。\n⑤文字脱漏讹～。\n【夺标】\n①争夺锦标；争当冠军。\n②夺到锦标；争得冠军。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-夺"},{"id":"glyph-seal-5942","script":"seal","character":"奂","reading":"huàn","description":"huàn：(1)盛，多。\n(2)文采鲜明。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奂"},{"id":"glyph-seal-5944","script":"seal","character":"奄","reading":"yǎn；yān","description":"yǎn：(1)覆盖～有天下。\n(2)忽然，突然～弃（忽然抛弃）。～忽（忽然，如～～如神”）。～然。\n(3)气息微弱～～一息。\nyān：(1)古同阉”，指宦官。\n(2)古同淹”，停留，久留。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奄"},{"id":"glyph-seal-5947","script":"seal","character":"奇","reading":"qí；jī","description":"qí：(1)特殊的，稀罕，不常见的～闻。～迹。～志。～观。～妙。～巧。～耻大辱。\n(2)出人意料的，令人不测的～兵。～计。～袭。出～制胜。\n(3)惊异，引以为奇～怪。惊～。不足为～。\n偶；\njī：(1)数目不成双的，与偶”相对～数（不能被二整除的数，如一、三、五、七、九等，正的奇数亦称单数”）。\n(2)零数～零（不满整数的数）。～羡（赢余，积存的财物）。有～（如八分～～”即八分多一点）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奇"},{"id":"glyph-seal-5948","script":"seal","character":"奈","reading":"nai；nài","description":"nài：如何，怎样～何。怎～。无～何（无可如何）。～……何（中间加代词，如奈我何”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奈"},{"id":"glyph-seal-5949","script":"seal","character":"奉","reading":"fèng","description":"fèng：(1)恭敬地用手捧着～觞（举杯祝酒）。～献。～祀。～承（恭维，讨好。承”读轻声）。\n(2)尊重，遵守～公守法。～为圭臬（把某些言论或事物当作准则）。～行故事（按老规定办事）。\n(3)敬辞，用于自己的举动涉及对方时～告。～还（huán）。～陪。～劝。～迎（ａ．敬辞，迎接；ｂ．奉承）。～赠。\n(4)信仰信～。素～佛教。\n(5)供养，伺候～养。供～。侍～。\n(6)姓。\n(7)古同俸”，薪金。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奉"},{"id":"glyph-seal-594b","script":"seal","character":"奋","reading":"fèn","description":"⒈鸟类展翅～飞。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奋"},{"id":"glyph-seal-594e","script":"seal","character":"奎","reading":"kuí","description":"kuí：(1)星名，二十八宿之一。\n(2)姓。\n〔～宁〕药名，白色结晶或无定形粉末，是治疗疟疾的特效药。亦称金鸡纳碱”、金鸡纳霜”。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奎"},{"id":"glyph-seal-594f","script":"seal","character":"奏","reading":"zòu","description":"zòu：(1)作乐（yuè），依照曲调吹弹乐器演～。～国歌。～鸣曲。\n(2)封建时代臣子对皇帝陈述意见或说明事情启～。～议。～疏。～折。～本。～对。\n(3)呈现，取得～效。～功。～捷（取得胜利）。大～奇功。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奏"},{"id":"glyph-seal-5951","script":"seal","character":"契","reading":"qì；qiè；xiè","description":"qì：(1)证券，证明买卖、抵押、租赁等关系的文书～约。～据。房～。\n(2)相合，相投相～。～合。默～。～友。～分（fèn）（投合无间的情分）。～厚。\n(3)用刀雕刻～刻。～舟求剑。\n(4)刻的文字，近代称甲骨文书～。～文（甲骨文）。\n〔～机〕指事物转化的关键。\nqiè：古同锲”，用刀子刻。\nxiè：古人名，中国商朝的祖先，传说是舜的臣，助禹治水有功而封于商。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-契"},{"id":"glyph-seal-5954","script":"seal","character":"奔","reading":"bēn；bèn","description":"bēn：急走，跑～跑。～驰。～突（横冲直撞；奔驰）。～流。～腾。～忙。～波（劳苦奔走）。～放（疾驰。喻气势雄伟，不受拘束）。私～（女子私自投奔所爱的人，或跟他一起逃走）。\nbèn：(1)直往，趋向投～。～东走。他都～六十了（将近六十岁）。\n(2)为某种目的而尽力去做～命。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奔"},{"id":"glyph-seal-5955","script":"seal","character":"奕","reading":"yì","description":"yì：(1)围棋～之始作，必起自战国。”\n(2)下棋使弈秋诲二人～。”\n(3)大息金消石，往小来～。”\n(4)美貌张华短章，～～清畅。”","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奕"},{"id":"glyph-seal-5956","script":"seal","character":"奖","reading":"jiǎng","description":"劝勉;鼓励\n辅助\n⒉称赞，表扬夸～。嘉～。～罚分明。\n⒊为了鼓励、表扬而给予的荣誉或财物等～状。～章。～金。～品。\n⒋指彩金抽～券。中头～。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奖"},{"id":"glyph-seal-5958","script":"seal","character":"奘","reading":"zàng；zhuǎng","description":"zàng：(1)壮大，多用于人名，如中国唐代和尚玄奘”。\n(2)说话粗鲁，态度生硬这个人真～。\nzhuǎng：粗大身高腰～。这棵树真～。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奘"},{"id":"glyph-seal-595a","script":"seal","character":"奚","reading":"xī","description":"xī：(1)古代指被役使的人～三百人”。～奴。\n(2)文言疑问代词，相当于胡”、何”～（为什么）不去也？子将～（什么）先？水～（何处）自至？\n(3)姓。","enabled":true,"collection":"篆字扩展","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奚"},{"id":"glyph-seal-5960","script":"seal","character":"奠","reading":"diàn","description":"diàn：(1)向死者供献祭品致敬祭～。～酒。\n(2)稳固地安置～都（dū）。～基。～定（使稳固安定，如～～基础”）。","enabled":true,"collection":"常用汉字","source":"https://github.com/pwxcoo/chinese-xinhua/blob/fe6d6c2e8baa82187f4c96bbe042e43f96c05666/data/word.json#字-奠"}];
